    "ta": "வழங்கப்பட்ட விவரங்கள் சரியானவை என்று உறுதியளிக்கிறேன், நேரடி மானிய சரிபார்ப்புக்கு ஒப்புதல் அளிக்கிறேன்.",
    "te": "అందించిన వివరాలు సరైనవని ధృవీకరిస్తున్నాను మరియు డీబీటీ పరిశీలనకు అంగీకరిస్తున్నాను.",
    "kn": "ಒದಗಿಸಲಾದ ವಿವರಗಳು ನಿಖರವಾಗಿವೆ ಎಂದು ಘೋಷಿಸುತ್ತೇನೆ ಮತ್ತು ಡಿಬಿಟಿ ಪರಿಶೀಲನೆಗೆ ಒಪ್ಪಿಗೆ ನೀಡುತ್ತೇನೆ.",
    "ml": "നൽകിയ വിവരങ്ങൾ കൃത്യമാണെന്ന് സാക്ഷ്യപ്പെടുത്തുന്നു, ഡിബിടി പരിശോധനയ്ക്ക് സമ്മതിക്കുന്നു.",
    "bn": "আমি ঘোষণা করছি যে প্রদত্ত বিবরণ সঠিক এবং ডিবিটি যাচাইকরণের সম্মতি দিচ্ছি।",
    "mr": "मी घोषित करतो की दिलेली माहिती खरी आहे आणि डीबीटी पडताळणीस संमती देतो.",
    "gu": "હું ખાતરી આપું છું કે આપેલી વિગતો સાચી છે અને ડીબીટી ચકાસણી માટે સંમતિ આપું છું.",
    "pa": "ਮੈਂ ਐਲਾਨ ਕਰਦਾ ਹਾਂ ਕਿ ਦਿੱਤੇ ਵੇਰਵੇ ਸਹੀ ਹਨ ਅਤੇ ਡੀਬੀਟੀ ਤਸਦੀਕ ਲਈ ਸਹਿਮਤੀ ਦਿੰਦਾ ਹਾਂ।",
    "or": "ମୁଁ ଘୋଷଣା କରୁଛି ଯେ ପ୍ରଦତ୍ତ ବିବରଣୀ ସଠିକ୍ ଏବଂ ଡିବିଟି ଯାଞ୍ଚ ପାଇଁ ସହମତି ପ୍ରଦାନ କରୁଛି।",
    "as": "মই ঘোষণা কৰোঁ যে দিয়া তথ্যসমূহ সঠিক আৰু ডিবিটি পৰীক্ষণৰ সন্মতি দিছোঁ।",
