  "pfmsDesc": {
    "en": "Direct Benefit Transfer (DBT) will be credited directly to your bank account via PFMS gateway.",
    "hi": "प्रत्यक्ष लाभ अंतरण (DBT) सीधे आपके बैंक खाते में PFMS पोर्टल द्वारा जमा किया जाएगा।",
    "ta": "நேரடி மானியம் (DBT) பிஎஃப்எம்எஸ் தளம் மூலம் உங்கள் வங்கிக் கணக்கில் நேரடியாக வரவு வைக்கப்படும்.",
    "te": "ప్రత్యక్ష ప్రయోజన బదిలీ (DBT) PFMS గేట్‌వే ద్వారా నేరుగా మీ బ్యాంక్ ఖాతాలో జమ అవుతుంది.",
    "kn": "ನೇರ ನಗದು ವರ್ಗಾವಣೆ (DBT) ಪಿಎಫ್‌ಎಂಎಸ್ ಗೇಟ್‌ವೇ ಮೂಲಕ ನೇರವಾಗಿ ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಜಮೆಯಾಗುತ್ತದೆ.",
    "ml": "നേരിട്ടുള്ള ആനുകൂല്യ കൈമാറ്റം (DBT) പിഎഫ്എംഎസ് വഴി ബാങ്ക് അക്കൗണ്ടിലേക്ക് എത്തും.",
    "bn": "প্রত্যক্ষ সুবিধা হস্তান্তর (ডিবিটি) সরাসরি আপনার ব্যাঙ্ক অ্যাকাউন্টে জমা হবে।",
    "mr": "प्रत्यक्ष लाभ हस्तांतरण (डीबीटी) थेट तुमच्या बँक खात्यात जमा केले जाईल.",
    "gu": "ડાયરેક્ટ બેનિફિટ ટ્રાન્સફર (DBT) સીધા તમારા બેંક ખાતામાં જમા કરવામાં આવશે.",
    "pa": "ਸਿੱਧਾ ਲਾਭ ਤਬਾਦਲਾ (DBT) ਸਿੱਧਾ ਤੁਹਾਡੇ ਬੈਂਕ ਖਾਤੇ ਵਿੱਚ ਜਮ੍ਹਾਂ ਕੀਤਾ ਜਾਵੇਗਾ।",
    "or": "ପ୍ରତ୍ୟକ୍ଷ ଲାଭ ହସ୍ତାନ୍ତର (DBT) ସିଧାସଳଖ ଆପଣଙ୍କ ବ୍ୟାଙ୍କ ଖାତାରେ ଜମା ହେବ।",
    "as": "প্ৰত্যক্ষ লাভ হস্তান্তৰ (DBT) পোনপটীয়াকৈ আপোনাৰ বেংক একাউণ্টত জমা হ’ব।",
    "ur": "براہ راست فائدہ کی منتقلی (DBT) سیدھے آپ کے بینک اکاؤنٹ میں جمع ہوگی۔"
},
