    "gu": "સત્તાવાર દસ્તાવેજ ચકાસણીને આધિન પ્રાથમિક લાયકાત.",
    "pa": "ਅਧਿਕਾਰਤ ਦਸਤਾਵੇਜ਼ ਤਸਦੀਕ ਦੇ ਅਧੀਨ ਮੁੱਢਲੀ ਯੋਗਤਾ।",
    "or": "ଅଧିକାରିକ ପ୍ରମାଣପତ୍ର ଯାଞ୍ଚ ସାପେକ୍ଷ ପ୍ରାରମ୍ଭିକ ଯୋଗ୍ୟତା।",
