  "schemesSubtitleText": {
    "en": "Central & state government welfare schemes tailored to your trade, background, and social category.",
    "hi": "आपके व्यवसाय, पृष्ठभूमि और सामाजिक श्रेणी के अनुकूल केंद्र व राज्य सरकार की कल्याणकारी योजनाएं।",
    "ta": "உங்கள் தொழில், பின்னணி மற்றும் சமூகப் பிரிவுக்கு ஏற்ற மத்திய மற்றும் மாநில அரசு நலத்திட்டங்கள்.",
    "te": "మీ వృత్తి, నేపథ్యం మరియు సామాజిక వర్గానికి తగిన కేంద్ర, రాష్ట్ర సంక్షేమ పథకాలు.",
    "kn": "ನಿಮ್ಮ ವೃತ್ತಿ, ಹಿನ್ನೆಲೆ ಮತ್ತು ಸಾಮಾಜಿಕ ವರ್ಗಕ್ಕೆ ಸೂಕ್ತವಾದ ಸರ್ಕಾರಿ ಯೋಜನೆಗಳು.",
    "ml": "നിങ്ങളുടെ തൊഴിലിനും പശ്ചാത്തലത്തിനും അനുയോജ്യമായ സർക്കാർ ക്ഷേമ പദ്ധതികൾ.",
    "bn": "আপনার পেশা, পটভূমি এবং সামাজিক শ্রেণীর জন্য উপযোগী সরকারি কল্যাণ প্রকল্প।",
    "mr": "तुमच्या व्यवसायासाठी आणि प्रवर्गासाठी केंद्र व राज्य शासनाच्या योजना.",
    "gu": "તમારા વ્યવસાય અને કેટેગરી માટે અનુકૂળ સરકારી કલ્યાણકારી યોજનાઓ.",
    "pa": "ਤੁਹਾਡੇ ਕਿੱਤੇ ਅਤੇ ਸ਼੍ਰੇਣੀ ਲਈ ਢੁਕਵੀਆਂ ਕੇਂਦਰੀ ਤੇ ਰਾਜ ਭਲਾਈ ਸਕੀਮਾਂ।",
    "or": "ଆପଣଙ୍କ ବ୍ୟବସାୟ, ପୃଷ୍ଠଭୂମି ଏବଂ ସାମାଜିକ ବର୍ଗ ଅନୁଯାୟୀ କେନ୍ଦ୍ର ଓ ରାଜ୍ୟ ସରକାରୀ ଯୋଜନା।",
    "as": "আপোনাৰ বৃত্তি, পটভূমি আৰু শ্ৰেণীৰ বাবে উপযোগী চৰকাৰী কল্যাণমূলক আঁচনি।",
    "ur": "آپ کے پیشے، پس منظر اور سماجی زمرے کے مطابق مرکزی و ریاستی فلاحی اسکیمیں۔"
},
