  "welcomeGreeting": {
    "en": "Hi! I'm your Skill Bridge assistant. I will ask you 10 simple questions to understand your background, skills, and goals. Speak or tap to answer.",
    "hi": "नमस्ते! मैं आपका स्किल ब्रिज सहायक हूँ। आपकी पृष्ठभूमि, कौशल और लक्ष्यों को समझने के लिए मैं आपसे 10 सरल प्रश्न पूछूँगा। उत्तर देने के लिए बोलें या टैप करें।",
    "ta": "வணக்கம்! நான் உங்கள் ஸ்கில் பிரிட்ஜ் உதவியாளர். உங்கள் பின்னணி, திறன்கள் மற்றும் இலக்குகளைப் புரிந்துகொள்ள 10 எளிய கேள்விகளைக் கேட்பேன். பதிலளிக்க பேசவும் அல்லது தட்டவும்.",
    "te": "నమస్కారం! నేను మీ స్కిల్ బ్రిడ్జ్ అసిస్టెంట్‌ని. మీ నేపథ్యం, నైపుణ్యాలు మరియు లక్ష్యాలను అర్థం చేసుకోవడానికి నేను 10 సాధారణ ప్రశ్నలను అడుగుతాను. సమాధానం ఇవ్వడానికి మాట్లాడండి లేదా ట్యాప్ చేయండి.",
    "kn": "ನಮಸ್ಕಾರ! ನಾನು ನಿಮ್ಮ ಸ್ಕಿಲ್ ಬ್ರಿಡ್ಜ್ ಸಹಾಯಕ. ನಿಮ್ಮ ಹಿನ್ನೆಲೆ, ಕೌಶಲ್ಯ ಮತ್ತು ಗುರಿಗಳನ್ನು ತಿಳಿಯಲು ನಾನು 10 ಸರಳ ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳುತ್ತೇನೆ. ಉತ್ತರಿಸಲು ಮಾತನಾಡಿ ಅಥವಾ ಟ್ಯಾಪ್ ಮಾಡಿ.",
    "ml": "നമസ്കാരം! ഞാൻ നിങ്ങളുടെ സ്കിൽ ബ്രിഡ്ജ് അസിസ്റ്റന്റാണ്. നിങ്ങളുടെ പശ്ചാത്തലവും കഴിവുകളും ലക്ഷ്യങ്ങളും മനസ്സിലാക്കാൻ ഞാൻ 10 ലളിതമായ ചോദ്യങ്ങൾ ചോദിക്കും. ഉത്തരം നൽകാൻ സംസാരിക്കുകയോ ടാപ്പ് ചെയ്യുകയോ ചെയ്യുക.",
    "bn": "নমস্কার! আমি আপনার স্কিল ব্রিজ সহকারী। আপনার পটভূমি, দক্ষতা এবং লক্ষ্য বোঝার জন্য আমি আপনাকে ১০টি সহজ প্রশ্ন করব। উত্তর দিতে কথা বলুন বা ট্যাপ করুন।",
    "mr": "नमस्कार! मी तुमचा स्किल ब्रिज सहाय्यक आहे. तुमची पार्श्वभूमी, कौशल्ये आणि ध्येये समजून घेण्यासाठी मी तुम्हाला १० सोपे प्रश्न विचारेन. उत्तर देण्यासाठी बोला किंवा टॅप करा.",
    "gu": "નમસ્તે! હું તમારો સ્કિલ બ્રિજ સહાયક છું. તમારી પૃષ્ઠભૂમિ, કૌશલ્ય અને લક્ષ્યોને સમજવા માટે હું તમને 10 સરળ પ્રશ્નો પૂછીશ. જવાબ આપવા માટે બોલો અથવા ટેપ કરો.",
    "pa": "ਸਤਿ ਸ੍ਰੀ ਅਕਾਲ! ਮੈਂ ਤੁਹਾਡਾ ਸਕਿੱਲ ਬ੍ਰਿਜ ਸਹਾਇਕ ਹਾਂ। ਤੁਹਾਡੇ ਪਿਛੋਕੜ, ਹੁਨਰ ਅਤੇ ਟੀਚਿਆਂ ਨੂੰ ਸਮਝਣ ਲਈ ਮੈਂ ਤੁਹਾਨੂੰ 10 ਸਧਾਰਨ ਸਵਾਲ ਪੁੱਛਾਂਗਾ। ਜਵਾਬ ਦੇਣ ਲਈ ਬੋਲੋ ਜਾਂ ਟੈਪ ਕਰੋ।",
    "or": "ନମସ୍କାର! ମୁଁ ଆପଣଙ୍କର ସ୍କିଲ୍ ବ୍ରିଜ୍ ସହାୟକ। ଆପଣଙ୍କର ପୃଷ୍ଠଭୂମି, ଦକ୍ଷତା ଏବଂ ଲକ୍ଷ୍ୟ ବୁଝିବା ପାଇଁ ମୁଁ ଆପଣଙ୍କୁ ୧୦ଟି ସରଳ ପ୍ରଶ୍ନ ପଚାରିବି। ଉତ୍ତର ଦେବା ପାଇଁ କୁହନ୍ତୁ କିମ୍ବା ଟ୍ୟାପ୍ କରନ୍ତୁ।",
    "as": "নমস্কাৰ! মই আপোনাৰ স্কিল ব্ৰিজ সহায়ক। আপোনাৰ পটভূমি, দক্ষতা আৰু লক্ষ্য বুজিবলৈ মই আপোনাক ১০টা সহজ প্ৰশ্ন সুধিম। উত্তৰ দিবলৈ কওক বা টিপক।",
    "ur": "ہیلو! میں آپ کا اسکل برج اسسٹنٹ ہوں۔ آپ کے پس منظر، مہارت اور مقاصد کو سمجھنے کے لیے میں آپ سے 10 آسان سوالات پوچھوں گا۔ جواب دینے کے لیے بولیں یا ٹیپ کریں۔"
  },
