    "ml": "വീൽചെയർ സൗകര്യം, കാഴ്ച സഹായം അല്ലെങ്കിൽ താഴത്തെ നിലയിലെ പരിശീലന കേന്ദ്രങ്ങൾ ആവശ്യമാണോ എന്ന് വ്യക്തമാക്കുക:",
