    "pa": "ਮੁਫਤ ਸਰਕਾਰੀ ਹੁਨਰ ਵਿਕਾਸ, ₹15,000 ਟੂਲਕਿੱਟ, DBT ਵਜ਼ੀਫ਼ੇ ਅਤੇ ਘੱਟ ਵਿਆਜ ਵਾਲੇ ਕਰਜ਼ੇ।",
