    "kn": "ನೋಂದಾಯಿತ ಕಲಿಯುವವರು ಮತ್ತು ಪ್ರಗತಿ ವಿಶ್ಲೇಷಣೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಲು ಲಾಗಿನ್ ಮಾಡಿ.",
