  "casteSubsidizedDbtNote": {
    "en": "Your caste status qualifies you for subsidized fee exemption and direct DBT benefits under this scheme.",
    "hi": "आपकी जाति स्थिति आपको इस योजना के तहत रियायती शुल्क छूट और सीधे डीबीटी लाभ के लिए योग्य बनाती है।",
    "ta": "உங்கள் சாதி நிலை இந்த திட்டத்தின் கீழ் கட்டண விலக்கு மற்றும் நேரடி DBT பலன்களுக்கு உங்களை தகுதிப்படுத்துகிறது.",
    "te": "మీ కుల స్థితి ఈ పథకం కింద రాయితీ రుసుము మినహాయింపు మరియు ప్రత్యక్ష DBT ప్రయోజనాలకు మిమ్మల్ని అర్హులుగా చేస్తుంది.",
    "kn": "ನಿಮ್ಮ ಜಾತಿ ಸ್ಥಿತಿಯು ಈ ಯೋಜನೆಯಡಿಯಲ್ಲಿ ರಿಯಾಯಿತಿ ಶುಲ್ಕ ವಿನಾಯಿತಿ ಮತ್ತು ನೇರ DBT ಪ್ರಯೋಜನಗಳಿಗೆ ನಿಮ್ಮನ್ನು ಅರ್ಹರನ್ನಾಗಿ ಮಾಡುತ್ತದೆ.",
    "ml": "നിങ്ങളുടെ ജാതി പദവി ഈ പദ്ധതിക്ക് കീഴിൽ സബ്‌സിഡി ഫീസ് ഇളവിനും നേരിട്ടുള്ള DBT ആനുകൂല്യങ്ങൾക്കും അർಹത നൽകുന്നു.",
    "bn": "আপনার জাতিগত অবস্থান আপনাকে এই প্রকল্পের অধীনে ভর্তুকি ফি ছাড় এবং সরাসরি ডিবিটি সুবিধার জন্য যোগ্য করে তোলে।",
    "mr": "तुमची जात स्थिती तुम्हाला या योजनेअंतर्गत सवलतीची फी माफी आणि थेट डीबीटी लाभांसाठी पात्र ठरवते.",
    "gu": "તમારી જાતિ સ્થિતિ તમને આ યોજના હેઠળ સબસિડીવાળી ફી મુક્તિ અને સીધા ડીબીટી લાભો માટે પાત્ર બનાવે છે.",
    "pa": "ਤੁਹਾਡੀ ਜਾਤੀ ਸਥਿਤੀ ਤੁਹਾਨੂੰ ਇਸ ਯੋਜਨਾ ਤਹਿਤ ਸਬਸਿਡੀ ਵਾਲੀ ਫੀਸ ਛੋਟ ਅਤੇ ਸਿੱਧੇ ਡੀਬੀਟੀ ਲਾਭਾਂ ਲਈ ਯੋਗ ਬਣਾਉਂਦੀ ਹੈ।",
    "or": "ଆପଣଙ୍କ ଜାତି ସ୍ଥିତି ଏହି ଯୋଜନା ଅଧୀନରେ ରିହାତି ଫି ଛାଡ ଏବଂ ପ୍ରତ୍ୟକ୍ଷ ଡିବିଟି ଲାଭ ପାଇଁ ଆପଣଙ୍କୁ ଯୋଗ୍ୟ କରେ।",
    "as": "আপোনাৰ জাতিৰ স্থিতি অনুসৰি আপুনি ৰেহাই মাচুল আৰু প্ৰত্যক্ষ ডিবিটি সুবিধাৰ বাবে যোগ্য।",
    "ur": "آپ کی ذات کی حیثیت آپ کو اس اسکیم کے تحت رعایتی فیس کی چھوٹ اور براہ راست ڈی بی ٹی فوائد کے لیے اہل بناتی ہے۔"
},
