export function getLocalizedAccessibility(acc: string, lang: SupportedLanguage = 'en'): string {
  if (!acc) return '';
  if (lang === 'en') return acc;
  const trimmed = acc.trim();
  if (ACCESSIBILITY_LOCALIZED[trimmed]?.[lang]) {
    return ACCESSIBILITY_LOCALIZED[trimmed][lang];
  }
  return acc;
}

export function getLocalizedFeeStatus(fee: string, lang: SupportedLanguage = 'en'): string {
  if (!fee) return '';
  if (lang === 'en') return fee;
  const trimmed = fee.trim();
  if (FEE_SUPPORT_LOCALIZED[trimmed]?.[lang]) {
    return FEE_SUPPORT_LOCALIZED[trimmed][lang];
  }
  return fee;
}


